const enPhrases=new RegExp(Object.keys(english).sort((a,b)=>b.length-a.length).map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
function translate(s){return language==='en'?s.replace(enPhrases,k=>english[k]):s}
function localize(root){
 if(language!=='en')return;
 function visit(el){
  if(el.nodeType===3){const text=el.nodeValue;if(/[А-Яа-яЁё]/.test(text))el.nodeValue=translate(text);return}
  if(el.nodeType!==1||el.localName==='svg'||el.hasAttribute('data-verbatim'))return;
  if(el.hasAttribute('aria-label'))el.setAttribute('aria-label',translate(el.getAttribute('aria-label')));
  for(const child of el.childNodes)visit(child)
 }
 visit(root)
}
function setLanguage(lang,explicit=true){
 try{localStorage.setItem('espidi-lang',lang)}catch{}
 if(explicit){
  const dest=new URL(location.href);
  dest.pathname=dest.pathname.replace(/faceplate(?:-en)?\.html$/,lang==='en'?'faceplate-en.html':'faceplate.html');
  history.replaceState(null,'',dest)
 }
 for(const a of document.querySelectorAll('.studio-links a'))a.textContent=a.dataset[lang];
 language=lang;document.documentElement.lang=lang;document.title='ESPidi — '+translate('Студия фейсплейтов');
 document.querySelector('.mast>span').textContent=translate('Студия фейсплейтов');nav.setAttribute('aria-label',translate('Разделы'));
 for(const el of document.querySelectorAll('.lang button'))el.setAttribute('aria-pressed',String(el.value===lang));
 render()
}

const undoStack=[],redoStack=[];
function capture(){return {items:project.items.map(o=>({...o})),chosen}}
function record(before){
 undoStack.push(before);if(undoStack.length>100)undoStack.shift();redoStack.length=0
}
function restore(state){project.items=state.items;chosen=state.chosen}
function step(back){
 const source=back?undoStack:redoStack,dest=back?redoStack:undoStack;
 if(drag||!source.length)return;
 dest.push(capture());restore(source.pop());render()
}
function historyButton(back){
 const enabled=(back?undoStack:redoStack).length>0;
 return '<button class="ghost" '+(enabled?'':'disabled ')+'onclick="step('+back+')">'+(back?'↶ Отменить':'↷ Повторить')+'</button>'
}
window.addEventListener('keydown',e=>{
 if(page!==1||drag||e.altKey||!(e.metaKey||e.ctrlKey)||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;
 const z=e.code==='KeyZ'||e.key.toLowerCase()==='z',y=e.ctrlKey&&!e.shiftKey&&(e.code==='KeyY'||e.key.toLowerCase()==='y');
 if(!z&&!y)return;
 e.preventDefault();step(z&&!e.shiftKey)
});
function setBlend(value){
 const o=project.items[chosen];if(!o||o.blend===value)return;record(capture());o.blend=value;render()
}

function item(name,svg){return {name,svg,x:0,y:0,scale:100,angle:0,blend:'normal'}}
function preset(i){return {name:NAMES[i],items:PRESETS[i].map(o=>({...item(o.name,o.svg),kind:o.name==='Маркировка'?'legend':'art'}))}}
let project=preset(0);
const config={family:'Смешанное',density:42,seed:48271,arcs:true,lines:true,rings:true,blocks:false};
function layer(o,i,hit){return '<g '+(hit?'data-item="'+i+'" ':'')+'transform="translate('+o.x*10+' '+o.y*10+') rotate('+o.angle+' 374 229) translate(374 229) scale('+o.scale/100+') translate(-374 -229)" style="mix-blend-mode:'+o.blend+'">'+o.svg+'</g>'}
function board(p,hit=false){
 const id='board'+(++serial)+'_';
 const join=p.join?joinFields(p):null;
 let defs=join?join.fields.map((shape,i)=>'<mask id="@@zone'+i+'" maskUnits="userSpaceOnUse" x="-10" y="-10" width="768" height="478">'+shape+'</mask>').join(''):'';
 const paint=(o,i)=>{
  const obj=layer(o,i,hit);
  return join&&o.role!==undefined?'<g mask="url(#@@zone'+o.role+')">'+obj+'</g>':obj
 };
 // Stencil infill must be above the base coat; artwork imported by hand stays above the composition.
 let art=join?join.backdrop:'';
 const labels=[];
 p.items.forEach((o,i)=>{
  if(o.kind==='legend')labels.push({o,i});else art+=paint(o,i)
 });
 art+=join?join.detail:'';
 if(labels.length){
  const gaps=labels.map(({o,i})=>'<g data-letter-gap="'+i+'" transform="'+tx(o)+'" stroke="black" stroke-width="2.2" stroke-linejoin="round">'+o.svg.replace(/fill="[^"]*"/g,'fill="black"')+'</g>').join('');
  defs+='<mask id="@@letters" maskUnits="userSpaceOnUse" x="0" y="0" width="748" height="458"><rect width="748" height="458" fill="white"/>'+gaps+'</mask>';
  art='<g mask="url(#@@letters)">'+art+'</g>'+labels.map(({o,i})=>layer(o,i,hit)).join('');
 }
 return BASE.replace(/\b([md]\d+)\b/g,id+'$1').replace('</defs>',defs+'</defs>').replace('<g id="canvasObjects"></g>','<g>'+art+'</g>').replaceAll('@@',id);
}
const button=(s,fn,cls='primary')=>'<button class="'+cls+'" onclick="'+fn+'">'+s+'</button>';
function header(s,b){return '<header><h1>'+esc(s)+'</h1>'+b+'</header>'}
function stage(p,hit=false){return '<div class="view"><div class="bar"><span>Предпросмотр</span><small>ESPidi v1</small></div><div class="stage '+(hit?'active':'')+'"><div class="ruler">0 <i></i>25<i></i>50<i></i>75 мм</div><div class="big">'+board(p,hit)+'</div><div class="measure"><i></i>74,8 × 45,8 мм<i></i></div></div><footer><span class="sw cu"></span>Медь под маской　<span class="sw au"></span>Открытый металл　<span class="sw si"></span>Шелкография</footer></div>'}
function openProject(p){undoStack.length=0;redoStack.length=0;project=structuredClone(p);chosen=project.items.length?0:-1;go(1)}
function go(i){page=i;render();window.scrollTo(0,0)}
function gallery(){return header('Библиотека фейсплейтов',button('+ Пустой фейсплейт',"openProject({name:'Новый фейсплейт',items:[]})",'ghost'))+'<div class="bar"><span>Готовые дизайны</span><small>Выбери панель, чтобы открыть её в редакторе.</small></div><div class="gallery">'+NAMES.map((name,i)=>'<button class="preset" onclick="openProject(preset('+i+'))"><div class="mat">'+board(preset(i))+'</div><div class="caption"><div><h2>'+name+'</h2><p>'+DESCS[i]+'</p></div><span class="arrow">↗</span></div></button>').join('')+'</div>'}
function options(list,value){return list.map(([v,t])=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(t)+'</option>').join('')}
function numeric(key,title,min,max,step){const o=project.items[chosen];return '<label class="row">'+title+'<input aria-label="'+title+'" type="number" min="'+min+'" max="'+max+'" step="'+step+'" value="'+o[key]+'" onchange="changeNumber(this,\''+key+'\')"></label>'}
function changeNumber(el,key){const o=project.items[chosen];if(!o)return;if(!el.value||!el.checkValidity()){el.value=o[key];return}if(o[key]===el.valueAsNumber)return;record(capture());o[key]=el.valueAsNumber;render()}
function selectObject(i){chosen=i;render()}
function editor(){
 const o=project.items[chosen];
 return header(project.name,'<div class="history-actions">'+historyButton(true)+historyButton(false)+button('↓ Скачать превью SVG','downloadSVG()','ghost')+'</div>')+'<div class="work">'+stage(project,true)+'<aside><div class="asidehead">Объекты</div>'+project.items.map((a,i)=>'<button class="obj '+(i===chosen?'selected':'')+'" onclick="selectObject('+i+')"><span>◇</span><b '+(a.imported?'data-verbatim':'')+'>'+esc(a.name)+'</b></button>').reverse().join('')+'<button class="import" onclick="document.getElementById(\'file\').click()">+ Добавить изображение</button><input id="file" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" hidden onchange="importFile(this.files[0])">'+(o?'<div class="asidehead sub">Свойства объекта</div><label class="row">Наложение<select onchange="setBlend(this.value)">'+options([['normal','Обычный'],['multiply','Умножение']],o.blend)+'</select></label>'+numeric('x','Сдвиг X, мм',-150,150,.1)+numeric('y','Сдвиг Y, мм',-150,150,.1)+numeric('scale','Масштаб, %',1,500,1)+numeric('angle','Поворот, °',-360,360,1)+'<div class="genbtn">'+button('Убрать объект','removeObject()','ghost')+'</div>':'')+'<p class="hint">Перетаскивай объект на панели. SVG остаётся векторным, а PNG перемещается без повторного растрирования.</p></aside></div><p class="notice">Прототип: скачивается визуальное превью, не производственный Gerber.</p>'
}
function removeObject(){if(chosen<0)return;record(capture());project.items.splice(chosen,1);chosen=Math.min(chosen,project.items.length-1);render()}
async function importFile(file){
 if(!file)return;
 const target=project;
 try{
 const src=await new Promise((ok,no)=>{const f=new FileReader();f.onload=()=>ok(f.result);f.onerror=no;f.readAsDataURL(file)});
 const im=new Image();im.src=src;await im.decode();
 const ratio=im.naturalWidth/im.naturalHeight;if(!(ratio>0))throw Error();
 const w=Math.min(380,220*ratio),h=w/ratio;
 const obj=item(file.name,'<image x="'+(374-w/2)+'" y="'+(185-h/2)+'" width="'+w+'" height="'+h+'" href="'+esc(src)+'"/>');
 if(target!==project)return;obj.imported=true;record(capture());target.items.push(obj);chosen=target.items.length-1;render()
 }catch{alert(translate('Не удалось открыть изображение. Попробуй SVG, PNG, JPEG или WebP.'))}
}
function point(svg,e){const pt=new DOMPoint(e.clientX,e.clientY);return pt.matrixTransform(svg.getScreenCTM().inverse())}
main.addEventListener('pointerdown',e=>{
 const g=e.target.closest('.stage.active [data-item]');if(drag||!g||e.button!==0)return;
 const svg=g.ownerSVGElement,i=Number(g.dataset.item),o=project.items[i],before=capture();chosen=i;drag={svg,g,i,before,start:point(svg,e),x:o.x,y:o.y,id:e.pointerId};svg.setPointerCapture(e.pointerId);e.preventDefault()
});
main.addEventListener('pointermove',e=>{
 if(!drag||drag.id!==e.pointerId)return;const d=drag,o=project.items[d.i],pt=point(d.svg,e);
 const coord=v=>Math.max(-150,Math.min(150,Math.round(v*10)/10));
 o.x=coord(d.x+(pt.x-d.start.x)/10);o.y=coord(d.y+(pt.y-d.start.y)/10);
 d.g.transform.baseVal.getItem(0).setTranslate(o.x*10,o.y*10);
 if(o.kind==='legend')d.svg.querySelector('[data-letter-gap="'+d.i+'"]')?.setAttribute('transform',tx(o));
 if(o.role===0)d.svg.querySelector('[data-stencil-source]')?.setAttribute('transform',tx(o))
});
for(const ev of ['pointerup','pointercancel','lostpointercapture'])main.addEventListener(ev,e=>{if(drag&&drag.id===e.pointerId){
 const d=drag,o=project.items[d.i];drag=null;
 if(ev==='pointercancel')restore(d.before);else if(o.x!==d.x||o.y!==d.y)record(d.before);
 render()
}});
function downloadSVG(){
 const svg=document.querySelector('.big svg').cloneNode(true);svg.removeAttribute('class');svg.setAttribute('width','748');svg.setAttribute('height','458');
 const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download=translate(project.name)+'-preview.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)
}
function random(seed){let s=seed>>>0;return ()=>{s=(Math.imul(1664525,s)+1013904223)>>>0;return s/4294967296}}
const allFamilies=['Орбиты','Секторы','Лиссажу','Трассы','Лабиринт','Разряды','Рельеф','Кристаллы','Автомат'];
function shuffle(list,next){const result=list.slice();for(let i=result.length-1;i>0;i--){const j=Math.floor(next()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
const probe=document.createElementNS('http://www.w3.org/2000/svg','svg');
probe.style.cssText='position:absolute;left:-99999px;top:0;width:748px;height:458px;visibility:hidden;pointer-events:none';probe.setAttribute('aria-hidden','true');document.body.append(probe);
function placeMotif(raw,frame){
 probe.innerHTML=raw;const box=probe.getBBox(),[x,y,w,h]=frame;
 const scale=Math.min(w/Math.max(box.width+4,1),h/Math.max(box.height+4,1));
 const dx=x+(w-box.width*scale)/2-box.x*scale,dy=y+(h-box.height*scale)/2-box.y*scale;
 return '<g transform="translate('+rounded(dx)+' '+rounded(dy)+') scale('+roundedScale(scale)+')">'+raw+'</g>'
}
function roundedScale(value){return Math.round(value*100000)/100000}
const modes=['Разлом','Линза','Переплетение','Трафарет'];
const descriptions=[
 'Один излом режет оба рисунка. Они сходятся по зубчатой кромке, оставляя между собой узкий просвет.',
 'Первый рисунок обрывается у кольца. Внутри продолжается другой; кольцо и касательная связывают их.',
 'Волнообразная лента проходит сквозь фон. В нескольких местах фон пересекает её сверху, как при плетении.',
 'Контуры первого рисунка становятся прорезями. Фактура второго видна только внутри них.'
];
const mixSettings={manual:false,families:['Орбиты','Трассы']};
function mixControls(){
 const s=mixSettings;
 const mode='<label class="row">Подбор<select aria-label="Подбор семейств" onchange="mixSettings.manual=this.value===\'manual\';build()">'+options([['auto','Авто · 2–4'],['manual','Выбрать вручную']],s.manual?'manual':'auto')+'</select></label>';
 if(!s.manual)return mode;
 return mode+'<div class="grouplabel">Семейства · '+s.families.length+' / 4</div><div class="chips">'+allFamilies.map(f=>{
  const on=s.families.includes(f),limit=on?s.families.length===2:s.families.length===4;
  return '<label><input type="checkbox" '+(on?'checked ':'')+(limit?'disabled ':'')+'onchange="chooseFamily(this)" value="'+f+'"> '+f+'</label>'
 }).join('')+'</div>'
}
function chooseFamily(input){
 const f=input.value;
 if(input.checked)mixSettings.families.push(f);else mixSettings.families=mixSettings.families.filter(x=>x!==f);
 build()
}
function mixedPlan(seed,k){
 const rng=random((Math.imul(seed+1,2246822519)^Math.imul(k+1,668265263))>>>0);
 if(mixSettings.manual)return shuffle(mixSettings.families,rng);
 return shuffle(allFamilies,rng).slice(0,2+(k+seed)%3)
}
// Masks are evaluated in board coordinates. A movable motif slides underneath its join.
const sheet='<rect x="-10" y="-10" width="768" height="478"';
const panelWhite=sheet+' fill="white"/>';
function field(d,c,w=0){return '<path d="'+d+'" fill="'+(w?'none':c)+'" stroke="'+(w?c:'none')+'" stroke-width="'+w+'" stroke-linejoin="round" stroke-linecap="round"/>'}
function circleField(x,y,r,c){return '<circle cx="'+x+'" cy="'+y+'" r="'+r+'" fill="'+c+'"/>'}
function shapeGeometry(o){
 // Everything but transparency becomes a wide white channel, including filled cells and dots.
 return o.svg.replace(/(fill|stroke)="(?!none")[^"]+"/g,'$1="white"').replace(/stroke-width="([^"]+)"/g,(m,w)=>'stroke-width="'+(12+Number(w)*2)+'"')
}
function tx(o){return 'translate('+o.x*10+' '+o.y*10+') rotate('+o.angle+' 374 229) translate(374 229) scale('+o.scale/100+') translate(-374 -229)'}
function joinFields(p){
 const j=p.join,{cx,cy,r,flip,mode}=j;
 const axis=x=>flip?748-x:x;
 let fields=[],detail='',backdrop='';
 const geometry=(d,c,w)=>field(d,c,w);
 if(mode===0){
  const zig='M'+axis(cx+92)+' -15 L'+axis(cx+12)+' '+(cy-31)+' H'+axis(cx-60)+' L'+axis(cx-108)+' '+(cy+32)+' H'+axis(cx-28)+' L'+axis(cx-176)+' 473';
  const half=zig+' H'+axis(-25)+' V-15 Z';
  const gap=geometry(zig,'black',12);
  fields=[geometry(half,'white')+gap,panelWhite+geometry(half,'black')+gap,geometry(zig,'white',51)+geometry(zig,'black',17),geometry(zig,'white',115)+geometry(zig,'black',68)];
  detail=pen(zig,colors[0],2);
 }else if(mode===1){
  const x=axis(cx),disc=(rr,c)=>circleField(x,cy,rr,c);
  const tangent='M'+axis(-16)+' '+(cy+r+51)+' H'+axis(cx-120)+' L'+axis(cx-69)+' '+(cy+r)+' H'+axis(769);
  fields=[panelWhite+disc(r+9,'black'),disc(r-4,'white'),disc(r+42,'white')+disc(r+13,'black'),geometry(tangent,'white',34)];
  detail=pen('M'+(x-r)+' '+cy+'a'+r+' '+r+' 0 1 0 '+(2*r)+' 0a'+r+' '+r+' 0 1 0 '+(-2*r)+' 0',colors[0],2.5)+pen(tangent,colors[2],1.6)
 }else if(mode===2){
  const course='M-70 '+(cy+92)+' C112 '+(cy+122)+' 196 '+(cy-164)+' 337 '+(cy-57)+' S529 '+(cy+146)+' 817 '+(cy-80);
  const stroke=(c,w)=>geometry(course,c,w);
  const bridges=[cx-232,cx+100].map(x=>'M'+x+' -30 l105 520');
  const bridgeFill=(c,w)=>bridges.map(d=>geometry(d,c,w)).join('');
  fields=[panelWhite+stroke('black',91)+bridgeFill('white',35),stroke('white',77)+bridgeFill('black',47),stroke('white',116)+stroke('black',96)+bridgeFill('black',47),bridgeFill('white',23)];
  detail='';backdrop=stroke('#384039',81);
 }else{
  const driver=p.items.find(o=>o.role===0);
  if(!driver)return {fields:[panelWhite,panelWhite,panelWhite,panelWhite],detail:'',backdrop:''};
  const shaped='<g data-stencil-source="true" transform="'+tx(driver)+'">'+shapeGeometry(driver)+'</g>';
  const cut='M'+axis(cx+155)+' -20 L'+axis(cx+15)+' '+cy+' l'+(flip?58:-58)+' 0 L'+axis(cx-106)+' 478 H'+axis(800)+' V-20Z';
  fields=[panelWhite,shaped,geometry(cut,'white'),geometry('M-20 '+(cy+92)+' H800','white',48)];
  // The base coat and infill both use the first motif's actual silhouette.
  backdrop=sheet+' fill="#556252" mask="url(#@@zone1)"/>';
 }
 return {fields,detail,backdrop}
}
function compose(k){
 const tag=String(config.seed).padStart(6,'0')+'-'+(k+1);
 if(config.family!=='Смешанное')return {...familyMotif(config.family,config.seed+k*2654435761,config.density,config),name:config.family+' / '+tag};
 const mode=(config.seed+k)%4,families=mixedPlan(config.seed,k);
 const rng=random((Math.imul(config.seed+1,3266489917)^Math.imul(k+1,668265263))>>>0);
 const cx=360+Math.round(rng()*109),cy=112+Math.round(rng()*64),r=84+Math.round(rng()*38),flip=rng()<.5;
 const x=flip?748-cx:cx;
 const frames=mode===0?[[flip?226:-72,-25,578,432],[flip?-60:220,-20,596,430],[30,-15,700,420],[0,24,748,369]]:
 mode===1?[[-20,-11,790,423],[x-r-24,cy-r-20,2*r+48,2*r+40],[x-r-42,cy-r-42,2*r+84,2*r+84],[-12,cy+r-37,772,170]]:
 mode===2?[[-15,-16,783,424],[-38,cy-145,831,311],[-30,cy-131,805,300],[26,4,689,445]]:
 [[35,13,681,375],[5,-5,736,395],[flip?-20:316,1,440,381],[10,cy+62,737,102]];
 const items=families.map((family,i)=>{
  const seed=Math.floor(rng()*4294967296),switches={arcs:family!=='Трассы',lines:family==='Трассы',rings:false,blocks:false};
  const raw=familyMotif(family,seed,Math.max(10,config.density*(i>1?.73:1)),switches).items.map(o=>o.svg).join('');
  return {...item(family,placeMotif(raw,frames[i])),role:i}
 });
 probe.replaceChildren();
 return {name:modes[mode]+' / '+tag,items,join:{mode,cx,cy,r,flip}}
}
function rounded(v){return Number(v.toFixed(2))}
function pointPath(points,close=false){return 'M'+points.map(p=>p.map(rounded).join(' ')).join('L')+(close?'Z':'')}
function pen(d,c,w=2,fill='none'){return '<path d="'+d+'" fill="'+fill+'" stroke="'+c+'" stroke-width="'+w+'" stroke-linejoin="round"/>'}
function composition(f,r,d){
 const between=(a,b)=>a+r()*(b-a),integer=(a,b)=>Math.floor(between(a,b+1));
 const tau=2*Math.PI,[gold,white,green]=colors,layers=[];
 const group=(name,art)=>layers.push(item(name,art.join('')));
 const disk=(x,y,radius,c)=>'<circle cx="'+rounded(x)+'" cy="'+rounded(y)+'" r="'+rounded(radius)+'" fill="'+c+'"/>';
 const box=(x,y,w,h,c)=>'<rect x="'+rounded(x)+'" y="'+rounded(y)+'" width="'+rounded(w)+'" height="'+rounded(h)+'" fill="'+c+'"/>';
 if(f==='Рельеф'){
  const hills=r()>.5?2:3;
  for(let h=0;h<hills;h++){
   const cx=(h+.5)*748/hills+between(-35,35),cy=between(80,220),rx=between(80,148),ry=between(75,128),phase=between(0,tau),waves=integer(2,5),a=[];
   const n=8+Math.round(d*23);
   for(let i=1;i<=n;i++){const p=[],k=i/n;
    for(let j=0;j<88;j++){const t=j*tau/88,m=k*(1+.16*Math.sin(waves*t+phase)+.12*Math.cos(3*t+k*2));p.push([cx+rx*m*Math.cos(t)+16*k*k,cy+ry*m*Math.sin(t)])}
    a.push(pen(pointPath(p,true),i%5===0?gold:h%2?green:white,i%5===0?2.8:1.5))}
   group('Горизонтали '+(h+1),a)
  }
 }else if(f==='Кристаллы'){
  // Crop a convex polygon against every perpendicular bisector (Voronoi cells).
  const n=10+Math.round(d*32),seeds=Array.from({length:n},()=>[between(12,737),between(10,390)]),cells=[],insets=[];
  for(const [x,y] of seeds){
   let p=[[16,18],[732,18],[732,386],[16,386]];
   for(const [u,v] of seeds){if(u===x&&v===y)continue;
    const side=([a,b])=>(a-(u+x)/2)*(u-x)+(b-(v+y)/2)*(v-y),next=[];
    for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length],sa=side(a),sb=side(b);if(sa<=0)next.push(a);if((sa<=0)!==(sb<=0)){const t=sa/(sa-sb);next.push([a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t])}}
    p=next
   }
   if(p.length<3)continue;
   const shrink=k=>p.map(([u,v])=>[x+(u-x)*k,y+(v-y)*k]);
   cells.push(pen(pointPath(shrink(.94),true),r()<.25?gold:green,2));
   if(r()<.33)for(const k of [.75,.56,.38])insets.push(pen(pointPath(shrink(k),true),white,1.6))
  }
  group('Ячейки Вороного',cells);group('Внутренние грани',insets)
 }else if(f==='Лабиринт'){
  const cols=16+Math.round(18*d),cell=696/cols,rows=Math.floor(315/cell),stack=[integer(0,cols*rows-1)],seen=new Set(stack),a=[],ends=[];
  const center=i=>[26+(i%cols+.5)*cell,22+(Math.floor(i/cols)+.5)*cell];
  while(stack.length){const i=stack[stack.length-1],x=i%cols,y=Math.floor(i/cols);
   const ns=[[x+1,y],[x-1,y],[x,y+1],[x,y-1]].filter(([u,v])=>u>=0&&v>=0&&u<cols&&v<rows&&!seen.has(v*cols+u));
   if(!ns.length){if(r()<.12)ends.push(disk(...center(i),cell*.17,gold));stack.pop();continue}
   const [u,v]=ns[integer(0,ns.length-1)],j=v*cols+u;seen.add(j);stack.push(j);
   a.push(pen(pointPath([center(i),center(j)]),Math.floor(x/(cols/3))===1?gold:white,cell*.32),disk(...center(j),cell*.159,Math.floor(x/(cols/3))===1?gold:white))
  }
  group('Ходы',a);group('Узлы',ends)
 }else if(f==='Разряды'){
  const a=[],ends=[],left=r()<.5,depth=3+Math.round(d*3);
  function limb(x,y,len,angle,lvl){
   const end=[x+Math.cos(angle)*len,y+Math.sin(angle)*len],p=[[x,y]];
   for(let j=1;j<5;j++){let t=j/5,off=between(-.11,.11)*len;p.push([x+(end[0]-x)*t-Math.sin(angle)*off,y+(end[1]-y)*t+Math.cos(angle)*off])}
   p.push(end);a.push(pen(pointPath(p),lvl>2?white:lvl?gold:green,1+lvl*.8));
   if(lvl){const turn=between(.32,.85);limb(...end,len*between(.6,.78),angle-turn,lvl-1);limb(...end,len*between(.59,.8),angle+turn,lvl-1)}
   else ends.push(disk(...end,2.5,gold))
  }
  limb(left?20:728,between(120,245),between(155,210),left?between(-.25,.25):Math.PI+between(-.25,.25),depth);
  group('Ветвление',a);group('Концы ветвей',ends)
 }else if(f==='Лиссажу'){
  const [m,n]=[[2,3],[3,4],[3,5],[4,5],[2,5]][integer(0,4)],phase=between(.1,2.9),a=[],b=[],count=3+Math.round(d*12),cx=between(304,434),cy=between(141,182);
  for(let j=0;j<count;j++){const p=[];for(let i=0;i<=250;i++){let t=tau*i/250;p.push([cx+290*Math.sin(m*t+phase+j*.022),cy+(115+j*1.5)*Math.sin(n*t)])}
   (j%3?a:b).push(pen(pointPath(p),j%3?green:gold,j===0?3:1.5))}
  group('Осциллограммы',a);group('Опорные кривые',b)
 }else if(f==='Автомат'){
  const cell=11-Math.round(d*5),cols=Math.ceil(710/cell),rows=Math.floor(334/cell),rule=[30,45,60,90,102,105,110,150][integer(0,7)],a=[],b=[];
  let v=Array.from({length:cols},()=>r()<.055?1:0);v[Math.floor(cols/2)]=1;
  for(let y=0;y<rows;y++){for(let x=0;x<cols;x++)if(v[x]){const accent=(y+2*x)%17<3;(accent?b:a).push(box(18+x*cell,18+y*cell,cell-1,cell-1,accent?gold:y%8<2?white:green))}
   v=v.map((c,x)=>(rule>>((v[(x+cols-1)%cols]<<2)|(c<<1)|v[(x+1)%cols]))&1)}
  group('Автомат / правило '+rule,a);group('Акценты',b)
 }
 return layers.filter(layer=>layer.svg.length)
}

function familyMotif(family,seed,density,switches){
 const rng=random(seed),range=(a,b)=>a+rng()*(b-a);
 if(!['Орбиты','Секторы','Трассы'].includes(family))return {items:composition(family,rng,density/100)};
 const cx=range(230,610),cy=range(77,202),n=Math.round(5+density*.28),items=[],int=(a,b)=>Math.floor(range(a,b+1));
 const style=(s,c,w)=>'<path d="'+s+'" fill="none" stroke="'+c+'" stroke-width="'+w+'"/>';
 function group(name,art){if(art)items.push(item(name,art))}
 const node=(x,y,r,c)=>'<circle cx="'+x+'" cy="'+y+'" r="'+r+'" fill="none" stroke="'+c+'" stroke-width="2"/>';
 function arc(x,y,r,a,b,c,w){const p=t=>[x+r*Math.cos(t),y+r*Math.sin(t)].join(' ');return style('M'+p(a)+' A'+r+' '+r+' 0 '+(b-a>Math.PI?1:0)+' 1 '+p(b),c,w)}
 let s='';
 if(switches.arcs){const count=family==='Секторы'?3:1;for(let j=0;j<count;j++){const x=count>1?110+j*235+range(-45,45):cx,y=cy+range(-35,35),a=range(-3,1),b=a+range(1.6,5.4),r=range(30,65);for(let i=0;i<(family==='Трассы'?Math.ceil(n/3):n);i++){s+=arc(x,y,r+i*4.7,a+Math.floor(i/6)*.18,b,colors[(j+Math.floor(i/5))%3],i%9===0?5:2)}}group('Дуги',s)}
 if(switches.lines){s='';const x=range(70,200),bend=range(30,100),y=range(32,145),dy=range(4,8),end=cx+range(50,120);
 for(let i=0;i<(family==='Трассы'?n:Math.ceil(n/2));i++){const a=y+i*dy,t=x+i*4;s+=style('M18 '+a+' H'+t+' l'+bend+' '+bend+' H'+(end+i*4)+' l55 -55 h'+(family==='Трассы'?240:38),colors[Math.floor(i/4)%3],i%6===0?4:2)}
 group('Трассы',s)}
 if(switches.rings){s='';const r=range(60,120),start=range(-3,0);for(let i=0;i<Math.ceil(n*.65);i++){const a=start+i*.19;s+=node(cx+Math.cos(a)*r,cy+Math.sin(a)*r,i%4===0?7:3,colors[i%3])}group('Кольца',s)}
 if(switches.blocks){s='';const x=range(36,170),y=range(225,290);for(let i=0;i<n;i++){s+='<rect x="'+(x+i*9)+'" y="'+(y+i%3*2)+'" width="'+int(3,7)+'" height="'+int(7,18)+'" fill="'+colors[i%3]+'"/>'}group('Блоки',s)}
 return {items}
}
function build(){variants=Array.from({length:4},(_,i)=>compose(i));render()}
function reroll(){
 const last=config.seed;
 do{config.seed=crypto.getRandomValues(new Uint32Array(1))[0]%1000000}while(config.seed===last);
 pick=0;build()}
function gen(){
 const name=variants[pick].name;
 return header('Генератор композиций',button('Открыть в редакторе →','openProject(variants[pick])'))+'<div class="work">'+stage(variants[pick])+'<aside><div class="asidehead">Композиция</div><label class="row">Семейство<select onchange="config.family=this.value;build()">'+options(['Смешанное',...allFamilies].map(x=>[x,x]),config.family)+'</select></label>' + (config.family==='Смешанное'?mixControls():['Орбиты','Секторы','Трассы'].includes(config.family)?'<div class="grouplabel">Элементы</div><div class="chips">'+Object.entries({arcs:'Дуги',lines:'Линии',rings:'Кольца',blocks:'Блоки'}).map(([k,t])=>'<label><input type="checkbox" '+(config[k]?'checked':'')+' onchange="config.'+k+'=this.checked;build()"> '+t+'</label>').join('')+'</div>':'') + '<label class="row">Плотность <output>'+config.density+' %</output></label><div style="padding:0 15px"><input aria-label="Плотность" type="range" min="1" max="100" value="'+config.density+'" oninput="this.parentNode.previousElementSibling.querySelector(\'output\').value=this.value+\' %\'" onchange="config.density=Number(this.value);build()"></div><label class="row">Сид<input type="number" aria-label="Сид" min="0" max="999999" value="'+config.seed+'" onchange="if(this.value && this.checkValidity()){config.seed=Number(this.value);build()}else this.value=config.seed"></label><div class="genbtn">'+button('Рандом · 4 варианта','reroll()')+'</div><p class="hint">'+(config.family==='Смешанное'?esc(variants[pick].items.map(o=>o.name).join(' + '))+'<br>'+descriptions[variants[pick].join.mode]:'При тех же настройках сид вернёт те же четыре композиции.')+'</p></aside></div><div class="varhead">Варианты <small class="smallnote">'+esc(name)+'</small></div><div class="variants">'+variants.map((p,i)=>'<button aria-pressed="'+(i===pick)+'" class="variant '+(i===pick?'pick':'')+'" onclick="pick='+i+';render()"><div>'+board(p)+'</div><span>'+p.name.split(' / ')[0]+' · 0'+(i+1)+'</span></button>').join('')+'</div>'
}
function render(){nav.innerHTML=tabs.map((s,i)=>'<button aria-current="'+(page===i?'page':'false')+'" class="'+(page===i?'on':'')+'" onclick="go('+i+')">'+s+'</button>').join('')+'<em>ESPidi v1　/　лицевая панель</em>';main.innerHTML=[gallery,editor,gen][page]();localize(nav);localize(main)}
variants=Array.from({length:4},(_,i)=>compose(i));setLanguage(language,false);
